/// <summary>
/// Bug 340352: [MS] E2E - RE-0031 Vendor Rebate - Batch Job Failed for Posting. MS SR# - 2603010030001346
/// </summary>
[ExtensionOf(classStr(TAMRebatePostUIBuilder))]
public final class METTAMRebatePostUIBuilder_Extension
{
}

Method.Source:
/// <summary>
/// Auto date population only visible when showDateAutoSet is true (METTAMRebatePostController_Provision only)
/// </summary>
public void postBuild()
{
    next postBuild();

    TAMRebatePostContract contract = this.dataContractObject();
    SysOperationUIBindInfo localBindInfo = this.bindInfo();

    localBindInfo.getDialogField(contract, methodStr(TAMRebatePostContract, metParmAutoSetDate)).visible(contract.metParmShowAutoSetDate());

    if (contract.parmRebateTransactionType() == TAMRebateTransactionType::Rebate)
    {
        contract.parmInitiatePrintInvoice(true);
        localBindInfo.getDialogField(contract, methodStr(TAMRebatePostContract, parmInitiatePrintInvoice)).value(true);
        localBindInfo.getDialogField(contract, methodStr(TAMRebatePostContract, parmInitiatePrintInvoice)).visible(true);

    }
    else
    {
        contract.parmInitiatePrintInvoice(false);
        localBindInfo.getDialogField(contract, methodStr(TAMRebatePostContract, parmInitiatePrintInvoice)).value(false);
        localBindInfo.getDialogField(contract, methodStr(TAMRebatePostContract, parmInitiatePrintInvoice)).visible(false);
    }
}
